1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Scenario = {
18	  customer: { yearsWithMHPCO: number };
19	  steps: Step[];
20	};
21	
22	export type Result = { premium: number } | { payout: number; remainingCap: number };
23	
24	const PROCESSING_FEE = 5;
25	const FIRST_INSURANCE_SURCHARGE = 0.1;
26	
27	const BASE_PREMIUMS: Record<string, number> = {
28	  sword: 100,
29	  amulet: 60,
30	  staff: 80,
31	};
32	
33	const quotePremium = (items: Item[]): number => {
34	  const policyBase = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
35	  const firstInsuranceSurcharge = policyBase * FIRST_INSURANCE_SURCHARGE;
36	  return Math.ceil(policyBase + firstInsuranceSurcharge + PROCESSING_FEE);
37	};
38	
39	export const runScenario = (scenario: Scenario): Result[] =>
40	  scenario.steps.map((step) => {
41	    if (step.op === "quote") return { premium: quotePremium(step.items) };
42	    throw new Error(`Unsupported step: ${step.op}`);
43	  });
